package com.bplus.share;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.database.Cursor;import android.provider.OpenableColumns;import android.widget.*;import org.json.*;import java.util.concurrent.*;
public class GroupChatActivity extends Activity{
 private FileSelection selection;private String gid;private LinearLayout rows;private ScrollView scroll;private TextView status;private final ExecutorService work=Executors.newSingleThreadExecutor();private final Handler handler=new Handler();private final Runnable tick=new Runnable(){public void run(){render();handler.postDelayed(this,1500);}};
 protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);gid=getIntent().getStringExtra("group");JSONObject g=LocalGroups.get(gid);if(g==null){finish();return;}selection=new FileSelection(this,"live_"+gid,this::refreshSelection);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);LinearLayout head=Ui.topBar(this,g.optString("name"),true,null);TextView info=Ui.t(this,"ⓘ",23,Ui.accent,App.cairoB);head.addView(info);info.setOnClickListener(v->details());TextView chatMenu=Ui.t(this,"⋮",25,Ui.text,App.cairoB);chatMenu.setContentDescription(getString(R.string.chat_options));Ui.pad(chatMenu,12,8,12,8,this);head.addView(chatMenu);chatMenu.setOnClickListener(v->ChatActions.show(this,"live_"+gid,()->{selection.back();refreshSelection();}));root.addView(head);status=Ui.sub(this,getString(R.string.group_live_note));root.addView(status);scroll=new ScrollView(this);rows=Ui.col(this);Ui.pad(rows,16,6,16,10,this);scroll.addView(rows);root.addView(scroll,Ui.lpW1());LinearLayout bar=Ui.row(this);Ui.pad(bar,12,9,12,14,this);TextView attach=Ui.t(this,"＋",28,Ui.dim,App.cairo);attach.setContentDescription(getString(R.string.send_files));bar.addView(attach,Ui.lp(Ui.dp(this,44),Ui.dp(this,44)));attach.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,73);});TextView emoji=Ui.t(this,"☺",25,Ui.dim,App.cairo);bar.addView(emoji,Ui.lp(Ui.dp(this,40),Ui.dp(this,44)));EditText input=new EditText(this);input.setTextColor(Ui.text);input.setHintTextColor(Ui.dim);input.setHint(R.string.message_hint);input.setTextSize(14);input.setBackground(Ui.round(Ui.field,22,this));Ui.pad(input,14,8,14,8,this);bar.addView(input,Ui.lpw(1));emoji.setOnClickListener(v->new AppDialog(this).setItems(new String[]{"👍","😊","❤️","😂","🙏"},(d,n)->input.append(new String[]{"👍","😊","❤️","😂","🙏"}[n])).show());TextView send=Ui.t(this,"➤",24,Ui.accent,App.cairo);bar.addView(send,Ui.lp(Ui.dp(this,44),Ui.dp(this,44)));send.setContentDescription(getString(R.string.send_now));send.setOnClickListener(v->{String text=input.getText().toString().trim();if(text.isEmpty())return;input.setText("");work.execute(()->{try{LocalGroups.sendText(gid,text);}catch(Exception e){error(e);}runOnUiThread(this::render);});});root.addView(bar);setContentView(root);if(!g.optBoolean("joined"))new AppDialog(this).setTitle(R.string.join_group).setMessage(getString(R.string.group_join_note,g.optString("hostName"))).setNegativeButton(R.string.cancel,(d,n)->finish()).setPositiveButton(R.string.join_group,(d,n)->work.execute(()->{try{LocalGroups.join(gid);runOnUiThread(this::render);}catch(Exception e){error(e);}})).show();}
 void error(Exception e){runOnUiThread(()->{if(!isFinishing())status.setText(getString(R.string.request_ended)+": "+e.getClass().getSimpleName()+" "+e.getMessage());});}
 void details(){JSONObject g=LocalGroups.get(gid);if(g==null)return;StringBuilder text=new StringBuilder(getString(R.string.group_live_note));JSONArray members=g.optJSONArray("members");if(members!=null)for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m!=null)text.append("\n").append(m.optString("name")).append(m.optBoolean("joined")?" ✓":" …");}AlertDialog.Builder d=new AppDialog(this).setTitle(g.optString("name")).setMessage(text.toString()).setNegativeButton(android.R.string.ok,null);if(LocalGroups.isHost(g))d.setPositiveButton(R.string.invite_member,(a,n)->invite());d.show();}
 void invite(){JSONArray peers=Store.peers();String[] names=new String[peers.length()];for(int i=0;i<names.length;i++)names[i]=peers.optJSONObject(i).optString("name");new AppDialog(this).setTitle(R.string.invite_member).setItems(names,(d,n)->new AppDialog(this).setMessage(getString(R.string.invite_confirm,names[n])).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.invite_member,(a,k)->work.execute(()->{try{LocalGroups.invite(gid,peers.optJSONObject(n));runOnUiThread(()->Toast.makeText(this,R.string.invite_sent,0).show());}catch(Exception e){error(e);}})).show()).show();}
 private boolean preserveSelectionScroll;private void refreshSelection(){if(rows==null)return;int y=scroll.getScrollY();java.util.HashSet<String> live=new java.util.HashSet<>();JSONArray saved=Store.thread("live_"+gid);for(int j=0;j<saved.length();j++){JSONObject item=saved.optJSONObject(j);if(item!=null)live.add(FileSelection.key(item));}for(int i=rows.getChildCount()-1;i>=0;i--){android.view.View row=rows.getChildAt(i);if(row.getTag() instanceof JSONObject&&!live.contains(FileSelection.key((JSONObject)row.getTag())))rows.removeViewAt(i);}last=saved.toString();for(int i=0;i<rows.getChildCount();i++){android.view.View row=rows.getChildAt(i);Object tag=row.getTag();if(tag instanceof JSONObject){JSONObject m=(JSONObject)tag;{row.setBackground(selection.has(m)?Ui.round(0x3058a4ff,12,this):null);row.setOnClickListener(selection.active()?v->selection.toggle(m):null);}}invalidateSelection(row);}scroll.post(()->scroll.scrollTo(0,y));}private void invalidateSelection(android.view.View v){v.invalidate();if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)invalidateSelection(g.getChildAt(i));}}
 private String last="";void render(){JSONArray t=Store.thread("live_"+gid);String now=t.toString();if(now.equals(last))return;last=now;rows.removeAllViews();for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m==null)continue;boolean me=m.optBoolean("me");LinearLayout cell=selection.row(m);cell.setTag(m);if(selection.has(m))cell.setBackground(Ui.round(0x3058a4ff,12,this));if(selection.active())cell.setOnClickListener(v->selection.toggle(m));cell.setGravity(me?android.view.Gravity.END:android.view.Gravity.START);cell.addView(Ui.t(this,m.optString("senderName"),11,Ui.accent,App.cairoSB));if(m.optString("kind").equals("file")){android.view.View card=FileCards.card(this,m,()->selection.toggle(m));cell.addView(selection.decorate(card,m));}else{TextView b=Ui.t(this,m.optString("body"),15,Ui.text,App.cairo);b.setMaxWidth(Ui.dp(this,285));b.setBackground(Ui.round(me?0xff203d52:Ui.card,15,this));Ui.pad(b,13,9,13,9,this);b.setOnLongClickListener(v->{selection.toggle(m);return true;});cell.addView(b);}cell.addView(Ui.t(this,m.optString("state"),10,Ui.dim,App.cairo));Ui.pad(cell,0,5,0,9,this);LinearLayout.LayoutParams gap=Ui.lp(-1,-2);gap.bottomMargin=Ui.dp(this,8);rows.addView(cell,gap);}if(!preserveSelectionScroll)scroll.post(()->scroll.fullScroll(android.view.View.FOCUS_DOWN));Store.set("groupRead_"+gid,String.valueOf(System.currentTimeMillis()));}
 public void onBackPressed(){if(selection!=null&&selection.back())return;super.onBackPressed();}
 protected void onResume(){super.onResume();handler.post(tick);}protected void onPause(){handler.removeCallbacksAndMessages(null);super.onPause();}protected void onDestroy(){work.shutdownNow();super.onDestroy();}
 protected void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(q!=73||r!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}work.execute(()->{try{String name="file";long size=-1;try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int ni=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),si=c.getColumnIndex(OpenableColumns.SIZE);if(ni>=0)name=c.getString(ni);if(si>=0&&!c.isNull(si))size=c.getLong(si);}}LocalGroups.sendFile(gid,uri,name,size);runOnUiThread(this::render);}catch(Exception e){error(e);}});}
}
